#!/usr/bin/env bash
# Creates .env with random local secrets the first time; never overwrites an existing one.
set -euo pipefail
cd "$(dirname "$0")/.."

[ -f .env ] && exit 0

rand() { od -An -tx1 -N32 /dev/urandom | tr -d ' \n'; }

umask 077
cat > .env <<EOF
# Local-only secrets generated by scripts/env.sh. Git-ignored; delete it to regenerate.
POSTGRES_PASSWORD=$(rand)
JWT_SECRET=$(rand)
GATEWAY_SECRET=$(rand)
EOF
echo "created .env with random local secrets"
